ind = wlanFieldIndices(cfg);
lltf = rx(pktOffset + (ind.LLTF(1):ind.LLTF(2)), :);
data = rx(pktOffset + (ind.HEData(1):ind.HEData(2)), :);

pktOffset = wlanPacketDetect(rx, 'CBW20');
if isempty(pktOffset), error('No packet'); end
lstf = rx(pktOffset + (ind.LSTF(1):ind.LSTF(2)), :);
cfo = wlanCoarseCFOEstimate(lstf, 'CBW20');
rx = frequencyOffset(rx, fs, -cfo);   % Communications Toolbox
lltf = rx(pktOffset + (ind.LLTF(1):ind.LLTF(2)), :);
fineOff = wlanSymbolTimingEstimate(lltf, 'CBW20');

coarse = wlanCoarseCFOEstimate(lstf, 'CBW40');
rx = frequencyOffset(rx, fs, -coarse);
fine = wlanFineCFOEstimate(lltf, 'CBW40');
rx = frequencyOffset(rx, fs, -fine);

lltfDemod = wlanLLTFDemodulate(lltf, 'CBW20');
chanEst = wlanLLTFChannelEstimate(lltfDemod, 'CBW20');
noiseVar = helperNoiseEstimate(lltfDemod);
