networkSimulator = wirelessNetworkSimulator.init;
central = bluetoothLENode('central', Position=[0 0 0]);
peripheral = bluetoothLENode('peripheral', Position=[10 0 0]);
cfg = bluetoothLEConnectionConfig(ConnectionInterval=0.01, AccessAddress='5DA44270');
configureConnection(cfg, central, peripheral);
addTrafficSource(central, networkTrafficOnOff(DataRate=100, PacketSize=100), DestinationNode=peripheral);
addNodes(networkSimulator, [central peripheral]);
run(networkSimulator, 1);
statistics(central)

startTime = datetime(2024, 5, 1, 12, 0, 0);
sc = satelliteScenario(startTime, startTime + hours(6), 60);
sat = satellite(sc, "leoSatelliteConstellation.tle");
gs = groundStation(sc, Latitude=48.2, Longitude=16.4, Name="Vienna");
ac = access(sat, gs);
intvls = accessIntervals(ac);
play(sc)

sat = satellite(sc, 7000e3, 0.001, 55, 30, 0, 0, Name="Sat1", OrbitPropagator="two-body-keplerian");
[pos, vel, t] = states(sat, CoordinateFrame="geographic");
tx = transmitter(sat, Frequency=12e9, Power=15);
gimbal(sat);
groundTrack(sat, LeadTime=1200);

gs = groundStation(sc, 42.3, -71.35, Name="Boston", MinElevationAngle=10);
rx = receiver(gs, GainToNoiseTemperatureRatio=5, RequiredEbNo=10);
[az, el, r] = aer(gs, sat);

sats = walkerStar(sc, 6371e3 + 780e3, 66, 6, 2, 86.4, Name="Iridium");
ac = access(sats, gs);
status = accessStatus(ac);   % 66-by-numSamples logical
fprintf('coverage %.1f %%\n', 100*mean(any(status, 1)))

cam = conicalSensor(sat, MaxViewAngle=30);
ac = access(cam, gs);
T = accessIntervals(ac)   % table: Source, Target, IntervalNumber, StartTime, EndTime, Duration
[s, t] = accessStatus(ac);

tx = transmitter(sat, Frequency=27.5e9, Power=20, BitRate=20);
gaussianAntenna(tx, DishDiameter=0.5);
rx = receiver(gs, GainToNoiseTemperatureRatio=25, RequiredEbNo=8);
lnk = link(tx, rx);
[e, t] = ebno(lnk);
plot(t, e); ylabel('Eb/No (dB)')

[az, el, r, t] = aer(gs, sat);
visible = el > gs.MinElevationAngle;
plot(t, el); yline(gs.MinElevationAngle, '--')

v = satelliteScenarioViewer(sc, ShowDetails=false, PlaybackSpeedMultiplier=50);
campos(v, 20, 0, 3e7);
play(sc);
snapshot(v, 'scenario.png')   % via viewer figure export (R2022b+)

